const canInvite=account=>account?.verified&&account.permissions?.canInvite===true&&window.DobbyAccess;
const showDialogControl=()=>{
 invitation.hidden=true;invite.removeAttribute('aria-expanded');
 invite.setAttribute('aria-haspopup','dialog');invite.setAttribute('aria-controls','access-invite-dialog');
};
const account=accountState();
if(childAccount(account)){invite.disabled=true;invite.title='Les invitations sont réservées aux parents du foyer.';}
else if(canInvite(account))showDialogControl();
invite.onclick=()=>{
 const current=accountState();
 if(childAccount(current))return;
 const verifying=!current?.verified&&nativeAccess()?.connectionState?.().householdId;
 if(canInvite(current)||verifying&&window.DobbyAccess){
  showDialogControl();
  void window.DobbyAccess.invite().catch(error=>c.notice(error.message));
  return;
 }
 invitation.hidden=!invitation.hidden;
 invite.removeAttribute('aria-haspopup');invite.setAttribute('aria-controls',invitation.id);
 invite.setAttribute('aria-expanded',String(!invitation.hidden));
};
